```tsx
import { useId } from "react";
import "./FocusProgress.css";

export interface FocusProgressProps {
  label: string;
  elapsedMinutes: number;
  totalMinutes: number;
}

function toSafeMinutes(value: number): number {
  return Number.isFinite(value) && value > 0 ? value : 0;
}

export function FocusProgress({
  label,
  elapsedMinutes,
  totalMinutes,
}: FocusProgressProps) {
  const labelId = useId();

  const total = toSafeMinutes(totalMinutes);
  const elapsed = Math.min(toSafeMinutes(elapsedMinutes), total);
  const percent = total === 0 ? 0 : Math.round((elapsed / total) * 100);

  const elapsedText = `${Math.round(elapsed)}`;
  const totalText = `${Math.round(total)}`;
  const valueText = `${elapsedText} of ${totalText} minutes, ${percent}% complete`;

  return (
    <div className="focus-progress">
      <div className="focus-progress__header">
        <span id={labelId} className="focus-progress__label">
          {label}
        </span>
        <span className="focus-progress__readout" aria-hidden="true">
          {elapsedText} / {totalText} min
        </span>
      </div>
      <div
        role="progressbar"
        tabIndex={0}
        aria-labelledby={labelId}
        aria-valuemin={0}
        aria-valuemax={total}
        aria-valuenow={elapsed}
        aria-valuetext={valueText}
        className="focus-progress__track"
      >
        <div
          className="focus-progress__fill"
          style={{ width: `${percent}%` }}
        />
      </div>
    </div>
  );
}
```

