 */
:root {
  --focus-progress-label: #3b3a36;
  --focus-progress-readout: #6b695f;
  --focus-progress-track: #e4e0d6;
  --focus-progress-fill: #5c7f6b;
  --focus-progress-focus-ring: #2f5d7c;
  --focus-progress-radius: 999px;
}

:root[data-theme="night"] {
  --focus-progress-label: #d9d6cc;
  --focus-progress-readout: #9a978c;
  --focus-progress-track: #2b2e33;
  --focus-progress-fill: #8fb8a0;
  --focus-progress-focus-ring: #9cc4e4;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    --focus-progress-label: #d9d6cc;
    --focus-progress-readout: #9a978c;
    --focus-progress-track: #2b2e33;
    --focus-progress-fill: #8fb8a0;
    --focus-progress-focus-ring: #9cc4e4;
  }
}

.focus-progress {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  width: 100%;
  font-family: inherit;
}

.focus-progress__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.focus-progress__label {
  color: var(--focus-progress-label);
  font-size: 1rem;
  font-weight: 500;
}

.focus-progress__readout {
  color: var(--focus-progress-readout);
  font-size: 0.875rem;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.focus-progress__track {
  position: relative;
  height: 0.5rem;
  width: 100%;
  overflow: hidden;
  border-radius: var(--focus-progress-radius);
  background-color: var(--focus-progress-track);
}

.focus-progress__track:focus {
  outline: none;
}

.focus-progress__track:focus-visible {
  outline: 2px solid var(--focus-progress-focus-ring);
  outline-offset: 3px;
}

.focus-progress__fill {
  height: 100%;
  border-radius: var(--focus-progress-radius);
  background-color: var(--focus-progress-fill);
  transition: width 400ms ease-out;
}

@media (prefers-reduced-motion: reduce) {
  .focus-progress__fill {
    transition: none;
  }
}
